G = 36
W = 6
K = 4
N = 9

# Verify
valid = True

# Check each week
for w in range(W):
    week = solution[w*G:(w+1)*G]
    # Each golfer assigned 0..8
    for g, group in enumerate(week):
        if not (0 <= group < N):
            print(f"Week {w}, golfer {g}: invalid group {group}")
            valid = False
    # Each group has exactly 4 golfers
    for n in range(N):
        count = week.count(n)
        if count != K:
            print(f"Week {w}, group {n}: has {count} golfers, expected {K}")
            valid = False

# Check no pair appears together more than once
from collections import defaultdict
pair_weeks = defaultdict(set)
for w in range(W):
    week = solution[w*G:(w+1)*G]
    # For each group
    for n in range(N):
        members = [g for g in range(G) if week[g] == n]
        for i in range(len(members)):
            for j in range(i+1, len(members)):
                g1, g2 = members[i], members[j]
                if w in pair_weeks[(g1, g2)]:
                    print(f"Pair ({g1},{g2}) appears together in weeks {pair_weeks[(g1,g2)]} and {w}")
                    valid = False
                pair_weeks[(g1, g2)].add(w)

if valid:
    print("All constraints satisfied!")
else:
    print("Invalid solution!")
